#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)
#define PI 3.141592
#define TAU 2.*PI
#define hue(v) ( .6 + .6 * cos( 6.3*(v) + vec3(0,23,21) ) )
#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))
#define COUNT 30.
#define N 5.
#define DISTORT .7
#define SQR(x) ((x)*(x))


float tt;

vec2 kalei(vec2 uv) { 
    float n = N;
    float r = TAU/n;

    for(float i=0.; i<n; i++) {     
    	uv = abs(uv);

    	uv *= rot(r*i-.09*tt);
    }

    uv = abs(uv) - (sin(.15*tt)+1.2);

    return uv;
}


float flower(vec2 uv) {
    float n = 5.;
    float a = atan(uv.y,uv.x);

    float d = length( uv) - cos(a*n);
    return smoothstep(fwidth(d), 0., abs(d));    
}


vec3 spiral(vec2 uv, float i) {  
    uv *= rot(i*PI+iTime*.33);
    uv += DISTORT*sin(5.*uv.yx);
	return flower(uv)*SQR(hue(i+tt*.2));
}

void mainImage(out vec4 O, vec2 C)
{
    O=vec4(0);
    vec2 uv = (C-.5*iResolution.xy)/iResolution.y;
vec3 r2 = normalize(vec3(uv.xy, 1.0 - dot(uv.xy, uv.xy) *10.));
   vec3 col = vec3(0);
    uv = kalei(uv*5.+r2.xy);

    float s = 1./COUNT;

    for(float i=0.; i<1.; i+=s) {   
        float z = fract(i-.01*tt);
        float fade = smoothstep(0., .1, 1.-abs(2.*z-1.));
        col += spiral(uv*z,i)*fade;
    }

    col = sqrt(col);

    vec3 p,r=iResolution,
    d=normalize(vec3((C-.5*r.xy)/r.y,1));  
    for(
        float i=0.,g=0.,e,s;
        ++i<99.;
        O.rgb+=mix(r/r,H(log(s)),.7)*.08*exp(-i*i*e))
    {
        p=g*d*col;

        p.z-=.4;
        p=R(p,normalize(vec3(1,1,0)),iTime*0.1);
        p.xy *= rot(i*PI+iTime*.1233);
        s=4.;
        for(int j=0;j++<8;)
            p=abs(p),p=p.x<p.y?p.zxy:p.zyx,
            s*=e=1.8/min(dot(p,p),1.3),
            p=p*e-vec3(12,3,3);
        g+=e=length(p.xz)/s;

    }
    O=pow(O,vec4(5));
 }
